pair-tool-results:
export function pairToolResults(calls, results) {
  const byId = new Map()
  const duplicate = new Set()
  for (const result of results) {
    if (byId.has(result.id)) duplicate.add(result.id)
    else byId.set(result.id, result)
  }
  const callIds = new Set(calls.map(call => call.id))
  const paired = calls.map(call => ({ call, result: byId.get(call.id) }))
  const unmatchedCalls = paired.filter(item => !item.result).map(item => item.call.id)
  const unmatchedResults = [...new Set(results.filter(result => !callIds.has(result.id) || duplicate.has(result.id)).map(result => result.id))]
  return { paired, unmatchedCalls, unmatchedResults }
}

derive-surface:
export function deriveSurface(events) {
  const view = []
  for (const event of events) {
    if (event.surfaceOp === 'replace') {
      const remove = new Set(event.sourceEventSeqs ?? [])
      for (let i = view.length - 1; i >= 0; i -= 1) {
        if (remove.has(view[i])) view.splice(i, 1)
      }
    }
    view.push(event.id)
  }
  return view
}

should-compact:
export function shouldCompact(tokens, contextWindow, thresholdRatio) {
  if (!Number.isFinite(tokens) || !Number.isFinite(contextWindow) || !Number.isFinite(thresholdRatio)) return false
  if (contextWindow <= 0 || thresholdRatio <= 0) return false
  return tokens / contextWindow >= thresholdRatio
}

plan-batches:
export function planBatches(calls) {
  const groups = []
  let current = []
  for (const call of calls) {
    if (call.concurrency === 'parallel') {
      current.push(call)
    } else {
      if (current.length > 0) {
        groups.push(current)
        current = []
      }
      groups.push([call])
    }
  }
  if (current.length > 0) groups.push(current)
  return groups
}

workspace-path:
import { isAbsolute, relative, resolve } from 'node:path'

export function isInsideWorkspace(root, candidate) {
  const rel = relative(resolve(root), resolve(candidate))
  return rel === '' || (!rel.startsWith('..') && !isAbsolute(rel))
}

turn-window:
export function openTurns(events) {
  const open = new Set()
  for (const event of events) {
    if (event.type === 'turn/start' && typeof event.turn === 'number') open.add(event.turn)
    else if (event.type === 'turn/end' && typeof event.turn === 'number') open.delete(event.turn)
  }
  return [...open].sort((a, b) => a - b)
}

assemble-text:
export function assembleText(chunks) {
  return chunks.map(chunk => chunk.text).join('')
}

missing-args:
export function missingArgs(args, required) {
  return required.filter(key => args[key] === undefined)
}

render-sections:
export function renderSections(sections) {
  return [...sections]
    .sort((a, b) => a.order - b.order)
    .map(section => section.text)
    .join('\n\n')
}

partition-inbox:
export function partitionInbox(items) {
  return {
    nextTurn: items.filter(item => item.kind === 'next-turn').map(item => item.id),
    nextStep: items.filter(item => item.kind === 'next-step').map(item => item.id),
  }
}

parse-jsonl:
export function parseJsonl(text) {
  const events = []
  let tornTail = false
  for (const line of text.split('\n')) {
    if (!line.trim()) continue
    try {
      events.push(JSON.parse(line))
    } catch {
      tornTail = true
      break
    }
  }
  return { events, tornTail }
}

dispose-effects:
export function disposeEffects(items) {
  const order = []
  for (let i = items.length - 1; i >= 0; i -= 1) {
    items[i].dispose()
    order.push(items[i].name)
  }
  return order
}

can-spawn:
export function canSpawn(active, depth, maxActive, maxDepth) {
  return active < maxActive && depth < maxDepth
}

safe-serialize:
export function safeSerialize(value) {
  try {
    return { ok: true, json: JSON.stringify(value) }
  } catch {
    return { ok: false, error: 'circular' }
  }
}

select-skills:
export function selectSkills(catalog, query) {
  const q = query.toLowerCase()
  return catalog
    .filter(skill => skill.name.toLowerCase().includes(q) || skill.description.toLowerCase().includes(q))
    .map(skill => skill.name)
}

stale-ref:
export function isStaleRef(refSnapshot, currentSnapshot) {
  return refSnapshot !== currentSnapshot
}

scale-point:
export function scalePoint(x, y, scale) {
  return { x: Math.round(x * scale), y: Math.round(y * scale) }
}

stale-reason:
export function staleReason(refSnapshot, currentSnapshot, refWindow, currentWindow) {
  if (refSnapshot !== currentSnapshot) return 'STALE_SNAPSHOT'
  if (refWindow !== currentWindow) return 'WINDOW_CHANGED'
  return null
}

parse-jsonrpc:
export function parseJsonRpcLine(line) {
  const data = JSON.parse(line)
  if (data.jsonrpc !== '2.0' || typeof data.method !== 'string') throw new Error('invalid')
  return data
}

card-status:
export function cardStatus(event) {
  if (event.type === 'approval/request') return 'waiting'
  if (event.type === 'tool/result') return event.isError ? 'failed' : 'done'
  return 'running'
}

normalize-span:
export function normalizeSpan(span) {
  return { name: span.name, status: span.status }
}

matrix-summary:
export function summarizeMatrix(rows) {
  const out = {}
  for (const row of rows) {
    out[row.scenario] ??= { pass: 0, fail: 0 }
    out[row.scenario][row.ok ? 'pass' : 'fail'] += 1
  }
  return out
}

audit-run:
export function auditRun(events) {
  const results = new Set(events.filter(event => event.type === 'tool/result').map(event => event.id))
  return events.filter(event => event.type === 'tool/call' && !results.has(event.id)).map(event => event.id)
}
